// 컴파일 결과 (타입이 사라진다)
function greet(name) {
  return `안녕, ${name}`;
}

// as const. 값을 리터럴로 굳힌다
const STATUS = ['todo', 'doing', 'done'] as const;
type Status = typeof STATUS[number];       // 'todo' | 'doing' | 'done'

// satisfies. 타입을 검사하되 추론은 좁게 유지한다
const routes = {
  home: '/',
  post: '/posts/:id',
} satisfies Record<string, string>;
routes.home;   // string 이 아니라 '/' 로 좁혀진 채 남는다

// 상태를 판별 유니온으로. 불가능한 조합을 애초에 못 만들게
type State =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'success'; data: Post[] }
  | { status: 'error'; message: string };

// isLoading 과 data 가 동시에 존재하는 이상한 상태가 타입 수준에서 불가능해진다
if (s.status === 'success') render(s.data);   // data 는 여기서만 보인다

