// eslint-disable-next-line @typescript-eslint/no-explicit-any -- 외부 SDK 타입이 틀림

import { z } from 'zod';

const User = z.object({
  id: z.number(),
  name: z.string(),
  email: z.string().email().optional(),
});
type User = z.infer<typeof User>;      // 스키마에서 타입이 나온다. 두 벌로 안 적는다

const user = User.parse(await res.json());       // 틀리면 여기서 터진다
const r = User.safeParse(raw);                    // 또는 성공/실패로 받는다
if (!r.success) return showError(r.error.issues);

async function api<T>(path: string, schema: z.ZodType<T>): Promise<T> {
  const res = await fetch(path);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);   // cs-net 5장
  return schema.parse(await res.json());
}

const users = await api('/users', z.array(User));   // 여기서부터 타입이 진짜다

